// Example: creating a Vue component
import Vue from 'vue';

function MyComponent() {
  return {
    template: '<div>Hello World</div>'
  };
}

// Example of a reactive data object in Vue
export default {
  data() {
    return {
      boxStyle: {
        width: '100px',
        height: '100px',
        backgroundColor: 'lightblue'
      }
    }
  }
}

// Example: a method that updates data
methods: {
  updateColor() {
    this.styleObject.color = 'green'
  }
}

// Adding a boolean data property
data() {
  return {
    isVisible: false
  }
}

// Example computed property for styles
computed: {
  dynamicStyle() {
    return {
      backgroundColor: this.isActive ? 'green' : 'gray'
    }
  }
}
